def arc(cx, cy, r1, r2, a0, a1, c, k=10):
    angles = [math.radians(a0 + (a1 - a0) * i / k) for i in range(k + 1)]
    outer = [(round(cx + r2 * math.cos(a)), round(cy + r2 * math.sin(a))) for a in angles]
    inner = [(round(cx + r1 * math.cos(a)), round(cy + r1 * math.sin(a))) for a in reversed(angles)]
    return P(outer + inner, c)


def head(cx, cy, r, a, da, c):
    pt = lambda rr, aa: (round(cx + rr * math.cos(math.radians(aa))), round(cy + rr * math.sin(math.radians(aa))))
    return P([pt(r - 12, a), pt(r + 12, a), pt(r, a + da)], c)


def line(x1, y1, x2, y2, w, c):
    d = math.hypot(x2 - x1, y2 - y1)
    nx, ny = -(y2 - y1) / d * w / 2, (x2 - x1) / d * w / 2
    return P([(round(x1 + nx), round(y1 + ny)), (round(x2 + nx), round(y2 + ny)),
              (round(x2 - nx), round(y2 - ny)), (round(x1 - nx), round(y1 - ny))], c)


def heart(cx, cy, s, c):
    pts = []
    for i in range(24):
        t = 2 * math.pi * i / 24
        x = 16 * math.sin(t) ** 3
        y = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t))
        pts.append((round(cx + x * s), round(cy + y * s)))
    return P(pts, c)


def gear(cx, cy, ro, ri, n, c):
    pts = []
    for i in range(n):
        a = 2 * math.pi * i / n
        for da, r in ((-0.30, ri), (-0.18, ro), (0.18, ro), (0.30, ri)):
            pts.append((round(cx + r * math.cos(a + da * 2 * math.pi / n)), round(cy + r * math.sin(a + da * 2 * math.pi / n))))
    return P(pts, c)


def shirt(cx, bottom, s, c):
    shape = [(-10, 0), (-4, -2), (4, -2), (10, 0), (16, 8), (10, 12), (9, 10), (9, 30), (-9, 30), (-9, 10), (-10, 12), (-16, 8)]
    return P([(round(cx + x * s), round(bottom - (30 - y) * s)) for x, y in shape], c)


def wave(y, c):
    top = [(90 + 10 * i, y + round(6 * math.sin(i * 0.8))) for i in range(17)]
    return P(top + [(x, yy + 12) for x, yy in reversed(top)], c)


def tower_band(y):
    x = 150 + (160 - y) * 20 / 106
    return P([(round(x), y), (round(x) + 36, y), (round(x) + 37, y - 5), (round(x) + 1, y - 5)], SB)


